-- Generated by dag_tools.systemlink.sql from the rule table in
-- dag_tools.systemlink.measurements. Do not edit by hand: a test
-- compares the generator's output against this file byte for byte.

with step_parameter as (
    select * from {{ var('mfg_trace_conf_step_parameter_relation') }}
),

attempt as (
    select
        result_id,
        started_at,
        part_number,
        serial_number,
        program_name,
        is_latest
    from {{ ref('test_result') }}
),

-- An inner join: a measurement whose attempt is not in the result
-- model has no unit, no program and no `is_latest_result`, and every
-- one of those is a required column here. Carrying the row with
-- nulls would publish a measurement nobody can attribute.
joined as (
    select
        step_parameter.*,
        attempt.started_at as attempt_started_at,
        attempt.part_number as attempt_part_number,
        attempt.serial_number as attempt_serial_number,
        attempt.program_name as attempt_program_name,
        attempt.is_latest as attempt_is_latest_result
    from step_parameter
    inner join attempt on attempt.result_id = step_parameter.result_id
),

-- Each pattern applied once, so the expressions below read columns.
extracted as (
    select
        joined.*,
        {{ mfg_trace_re_extract("trim(coalesce(measurement_text, ''))", "^([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*(?:±|\\+/-)\\s*([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*([A-Za-zµμΩ°%/^\\-\\d]*[A-Za-zµμΩ°%])?$", 1) }} as measurement_tolerance_center,
        {{ mfg_trace_re_extract("trim(coalesce(measurement_text, ''))", "^([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*(?:±|\\+/-)\\s*([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*([A-Za-zµμΩ°%/^\\-\\d]*[A-Za-zµμΩ°%])?$", 2) }} as measurement_tolerance_tol,
        {{ mfg_trace_re_extract("trim(coalesce(measurement_text, ''))", "^([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*(?:±|\\+/-)\\s*([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*([A-Za-zµμΩ°%/^\\-\\d]*[A-Za-zµμΩ°%])?$", 3) }} as measurement_tolerance_unit,
        {{ mfg_trace_re_extract("trim(coalesce(measurement_text, ''))", "^([<>=!≤≥]+)\\s*([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*([A-Za-zµμΩ°%/^\\-\\d]*[A-Za-zµμΩ°%])?$", 1) }} as measurement_comparator_op,
        {{ mfg_trace_re_extract("trim(coalesce(measurement_text, ''))", "^([<>=!≤≥]+)\\s*([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*([A-Za-zµμΩ°%/^\\-\\d]*[A-Za-zµμΩ°%])?$", 2) }} as measurement_comparator_value,
        {{ mfg_trace_re_extract("trim(coalesce(measurement_text, ''))", "^([<>=!≤≥]+)\\s*([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*([A-Za-zµμΩ°%/^\\-\\d]*[A-Za-zµμΩ°%])?$", 3) }} as measurement_comparator_unit,
        {{ mfg_trace_re_extract("trim(coalesce(measurement_text, ''))", "^([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*([A-Za-zµμΩ°%/^\\-\\d]*[A-Za-zµμΩ°%])?$", 1) }} as measurement_number_value,
        {{ mfg_trace_re_extract("trim(coalesce(measurement_text, ''))", "^([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*([A-Za-zµμΩ°%/^\\-\\d]*[A-Za-zµμΩ°%])?$", 2) }} as measurement_number_unit,
        {{ mfg_trace_re_extract("trim(coalesce(limits_text, ''))", "^([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*(?:±|\\+/-)\\s*([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*([A-Za-zµμΩ°%/^\\-\\d]*[A-Za-zµμΩ°%])?$", 1) }} as limits_tolerance_center,
        {{ mfg_trace_re_extract("trim(coalesce(limits_text, ''))", "^([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*(?:±|\\+/-)\\s*([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*([A-Za-zµμΩ°%/^\\-\\d]*[A-Za-zµμΩ°%])?$", 2) }} as limits_tolerance_tol,
        {{ mfg_trace_re_extract("trim(coalesce(limits_text, ''))", "^([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*(?:±|\\+/-)\\s*([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*([A-Za-zµμΩ°%/^\\-\\d]*[A-Za-zµμΩ°%])?$", 3) }} as limits_tolerance_unit,
        {{ mfg_trace_re_extract("trim(coalesce(limits_text, ''))", "^([<>=!≤≥]+)\\s*([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*([A-Za-zµμΩ°%/^\\-\\d]*[A-Za-zµμΩ°%])?$", 1) }} as limits_comparator_op,
        {{ mfg_trace_re_extract("trim(coalesce(limits_text, ''))", "^([<>=!≤≥]+)\\s*([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*([A-Za-zµμΩ°%/^\\-\\d]*[A-Za-zµμΩ°%])?$", 2) }} as limits_comparator_value,
        {{ mfg_trace_re_extract("trim(coalesce(limits_text, ''))", "^([<>=!≤≥]+)\\s*([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*([A-Za-zµμΩ°%/^\\-\\d]*[A-Za-zµμΩ°%])?$", 3) }} as limits_comparator_unit,
        {{ mfg_trace_re_extract("trim(coalesce(limits_text, ''))", "^([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*([A-Za-zµμΩ°%/^\\-\\d]*[A-Za-zµμΩ°%])?$", 1) }} as limits_number_value,
        {{ mfg_trace_re_extract("trim(coalesce(limits_text, ''))", "^([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*([A-Za-zµμΩ°%/^\\-\\d]*[A-Za-zµμΩ°%])?$", 2) }} as limits_number_unit
    from joined
),

-- The operator a limits text states, if the text states one at all.
stated as (
    select
        extracted.*,
        case
            when coalesce(limits_tolerance_center, '') <> '' then cast(null as varchar)
            when coalesce(limits_comparator_op, '') <> '' then nullif(trim(limits_comparator_op), '')
            when coalesce(limits_number_value, '') <> '' then cast(null as varchar)
            else cast(null as varchar)
        end as op_text
    from extracted
),

-- The deployment's comparator table is the only thing that says what
-- an operator MEANS and which side it bounds. This library ships no
-- rows for it, so a deployment that declares none covers none.
coded as (
    select
        stated.*,
        {% if var('mfg_trace_comparators') %}case{% for row in var('mfg_trace_comparators') %}
            when op_text = '{{ row['text'] | trim | replace("'", "''") }}' then '{{ row['code'] | replace("'", "''") }}'{% endfor %}
            else cast(null as varchar)
        end{% else %}cast(null as varchar){% endif %} as op_code,
        {% if var('mfg_trace_comparators') %}case{% for row in var('mfg_trace_comparators') %}
            when op_text = '{{ row['text'] | trim | replace("'", "''") }}' then '{{ row['bound'] | replace("'", "''") }}'{% endfor %}
            else cast(null as varchar)
        end{% else %}cast(null as varchar){% endif %} as op_bound
    from stated
),

parsed as (
    select
        coded.*,
        case
            when coalesce(measurement_tolerance_center, '') <> '' then cast(null as double)
            when coalesce(measurement_comparator_op, '') <> '' then cast(null as double)
            when coalesce(measurement_number_value, '') <> '' then case when cast(measurement_number_value as double) * 0 = 0 then cast(measurement_number_value as double) else cast(null as double) end
            else cast(null as double)
        end as parsed_measurement_num,
        case
            when coalesce(limits_tolerance_center, '') <> ''
                then cast(cast(limits_tolerance_center as {{ var('mfg_trace_decimal_type') }}) - cast(limits_tolerance_tol as {{ var('mfg_trace_decimal_type') }}) as double)
            when op_code is not null and op_bound = 'low'
                then case when cast(limits_comparator_value as double) * 0 = 0 then cast(limits_comparator_value as double) else cast(null as double) end
            else cast(null as double)
        end as parsed_low_limit_num,
        case
            when coalesce(limits_tolerance_center, '') <> ''
                then cast(cast(limits_tolerance_center as {{ var('mfg_trace_decimal_type') }}) + cast(limits_tolerance_tol as {{ var('mfg_trace_decimal_type') }}) as double)
            when op_code is not null and op_bound = 'high'
                then case when cast(limits_comparator_value as double) * 0 = 0 then cast(limits_comparator_value as double) else cast(null as double) end
            else cast(null as double)
        end as parsed_high_limit_num,
        case
            when coalesce(measurement_tolerance_center, '') <> '' then nullif(trim(measurement_tolerance_unit), '')
            when coalesce(measurement_comparator_op, '') <> '' then nullif(trim(measurement_comparator_unit), '')
            when coalesce(measurement_number_value, '') <> '' then nullif(trim(measurement_number_unit), '')
            else cast(null as varchar)
        end as parsed_measurement_units,
        case
            when coalesce(limits_tolerance_center, '') <> '' then nullif(trim(limits_tolerance_unit), '')
            when coalesce(limits_comparator_op, '') <> '' then nullif(trim(limits_comparator_unit), '')
            when coalesce(limits_number_value, '') <> '' then nullif(trim(limits_number_unit), '')
            else cast(null as varchar)
        end as parsed_limits_units
    from coded
)

select
    result_id,
    step_id,
    parameter_index,
    step_path,
    step_name,
    parameter_name,
    parsed_measurement_num as measurement_num,
    measurement_text,
    -- What the source supplied wins; a suffix parsed out of the text
    -- is only a fallback. The other direction silently relabels every
    -- row whose column and suffix disagree.
    coalesce(
        nullif(trim(units), ''),
        parsed_measurement_units,
        parsed_limits_units
    ) as units,
    parsed_low_limit_num as low_limit_num,
    parsed_high_limit_num as high_limit_num,
    limits_text,
    coalesce(nullif(trim(comparison_type), ''), op_code) as comparison_type,
    status,
    -- A measurement that is not a number is only a FAILURE where a
    -- limit is a number: that is what says a number was expected
    -- here. A status word against non-numeric limits parsed fine.
    (
        parsed_measurement_num is null
        and (
            parsed_low_limit_num is not null
            or parsed_high_limit_num is not null
        )
    ) as parse_failed,
    attempt_started_at as started_at,
    attempt_part_number as part_number,
    attempt_serial_number as serial_number,
    attempt_program_name as program_name,
    attempt_is_latest_result as is_latest_result,
    source_system,
    source_record_id,
    extracted_at,
    loaded_at
from parsed
